/// <summary>
/// MPJ_5013_ExciseRegisterEntry 
/// Service class to run the update and creation of new record
/// </summary>
class METUpdateExciseRegisterService extends SysOperationServiceBase
{
    SalesTable             salesTable;
    METExciseRegisterEntry metExciseRegisterEntry;
    InventSite             inventSite;
    CUSTINVOICEJOUR        custInvoiceJour;
    CustInvoiceTrans       custInvoiceTrans;
    SalesLine              salesLine;
    METInventTable         metInventTable;
}

Method.Source:
/// <summary>
/// MPJ_5013_ExciseRegister
/// Checks if run in batch or not.
/// </summary>
public void processOperation()
{
    
    int                    i;
    i= 0;
    delete_from metExciseRegisterEntry where metExciseRegisterEntry.OriginType == METOriginType::SalesOrder;
    ttsbegin;
    while select  inventSite
            where inventSite.METBondedWarehouse == NoYes::Yes
                join salesTable
            where inventSite.SiteId == salesTable.InventSiteId
                && salesTable.SalesStatus == SalesStatus::Invoiced
                join custInvoiceJour
            where SalesTable.salesid == custInvoiceJour.salesid
                join custInvoiceTrans
            where custInvoiceJour.SalesId == custInvoiceTrans.SalesId
                join metInventTable
            where custInvoiceTrans.ItemId == metInventTable.TariffItem
            && metInventTable.CustomsExcise != METCustomExcise::Blank
    {
        metExciseRegisterEntry.Lodgement              = int2Str(i);
        metExciseRegisterEntry.Site                   = inventSite.SiteId;
        metExciseRegisterEntry.ItemNo                 = custInvoiceTrans.ItemId;
        metExciseRegisterEntry.InventoryUnitOfMeasure = SalesLine::find(custInvoiceJour.SalesId).SalesUnit;
        metExciseRegisterEntry.ReceiptUnitOfMeasure   = SalesLine::find(custInvoiceJour.SalesId).SalesUnit;
        metExciseRegisterEntry.OriginType             = METOriginType::SalesOrder;
        metExciseRegisterEntry.OriginNumber           = salesTable.SalesId;
        metExciseRegisterEntry.OriginDocumentNumber   = custInvoiceJour.InvoiceId;
        metExciseRegisterEntry.CustomsExcise          = metInventTable.CustomsExcise;
        metExciseRegisterEntry.ReceiptQuantity        = custInvoiceTrans.Qty;
        metExciseRegisterEntry.Quantity               = -(metExciseRegisterEntry.ReceiptQuantity * 6);
        metExciseRegisterEntry.AvailableQuantity      = 0;
        metExciseRegisterEntry.Closed                 = NoYes::Yes;
        select salesLine
            where salesLine.ItemId == custInvoiceTrans.ItemId;
        metExciseRegisterEntry.LotId = salesLine.InventTransId;
        metExciseRegisterEntry.insert();
        this.availableQtyCalculation(metExciseRegisterEntry);
        i = i+1;
    }
    ttscommit;
    
}

    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// This method calcultes the available qty 
    /// </summary>
    /// <param name = "_metExciseRegisterEntrySales"> METExciseRegister table</param>
 
    public void availableQtyCalculation(metExciseRegisterEntry _metExciseRegisterEntrySales)
    {
        METExciseRegisterEntry metExciseRegisterEntryPurch;
        ttsbegin;

        while select forupdate metExciseRegisterEntryPurch
            where _metExciseRegisterEntrySales.ItemNo    == metExciseRegisterEntryPurch.ItemNo
            &&    _metExciseRegisterEntrySales.LotId     == metExciseRegisterEntryPurch.LotId
            &&    metExciseRegisterEntryPurch.OriginType == METOriginType::PurchaseOrder
            &&    metExciseRegisterEntryPurch.AvailableQuantity   > 0
        {
           
            metExciseRegisterEntryPurch.AvailableQuantity = metExciseRegisterEntryPurch.AvailableQuantity + _metExciseRegisterEntrySales.Quantity;
            if(metExciseRegisterEntryPurch.AvailableQuantity == 0)
            {
                metExciseRegisterEntryPurch.Closed = NoYes::Yes;
                
            }
            metExciseRegisterEntryPurch.update();
            break;
        }
       
        ttscommit;

       
    }
